import React, { useState } from 'react';
import { Trash2, Plus, Users, Play, Clock, Layers, Calendar, ShieldCheck, MapPin } from 'lucide-react';

const distributeSubjects = (subjectList, daysCount) => {
  const sorted = [...subjectList].sort((a, b) => a.code.localeCompare(b.code));
  const result = Array.from({ length: daysCount }, () => []);
  sorted.forEach((subject, index) => {
    result[index % daysCount].push(subject);
  });
  return result;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const handleAddProctor = () => {
    if (!pName || !pDayStart || !pDayEnd || !pTimeStart || !pTimeEnd) {
      return alert("Complete all proctor fields (Name, Dates, and Time Windows)!");
    }
    const updated = [...proctors, { 
      id: Date.now(), 
      name: pName.toUpperCase(), 
      dayStart: pDayStart, 
      dayEnd: pDayEnd,
      timeStart: pTimeStart,
      timeEnd: pTimeEnd
    }];
    onUpdate('proctors', updated);
    setPName("");
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert(`Add subjects for Year ${selectedYear} first!`);
    if (examDates.some(d => !d)) return alert("Set all exam dates first!");

    const dailySplit = distributeSubjects(yearSubjects, examDays);
    const finalGeneratedData = [];

    for (let dayIdx = 0; dayIdx < dailySplit.length; dayIdx++) {
      const daySubjects = dailySplit[dayIdx];
      const currentDate = examDates[dayIdx];

      // 1. ROOM ALLOCATION (Consecutive + Global Fallback)
      let availableRooms = rooms.filter(r => !globalSchedule.some(as => as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));

      if (roomSource === "Global" || availableRooms.length < sectionCount) {
        const globals = allDepartments.flatMap(d => d.rooms).filter(r => r.type === "Global" && !globalSchedule.some(as => as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));
        availableRooms = [...new Set([...availableRooms, ...globals])];
      }

      availableRooms.sort((a, b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      let chosenRoomNumbers = [];
      for (let i = 0; i <= availableRooms.length - sectionCount; i++) {
        const slice = availableRooms.slice(i, i + sectionCount);
        const isConsec = slice.every((r, idx) => idx === 0 || parseInt(r.number) === parseInt(slice[idx - 1].number) + 1);
        if (isConsec) { chosenRoomNumbers = slice.map(r => r.number); break; }
      }
      if (chosenRoomNumbers.length === 0) chosenRoomNumbers = availableRooms.slice(0, sectionCount).map(r => r.number);
      if (chosenRoomNumbers.length < sectionCount) return alert(`Not enough rooms for Day ${dayIdx + 1}`);

      // 2. SECTION ALLOCATION
      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        // --- PROCTOR VALIDATION ENGINE ---
        const validateProctor = (p) => (
          currentDate >= p.dayStart && currentDate <= p.dayEnd &&       // Day check
          startTime >= p.timeStart && endTime <= p.timeEnd &&           // Time check
          !globalSchedule.some(as => as.proctor === p.name && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)) // Conflict check
        );

        let proctor = proctors.find(validateProctor);

        if (!proctor || proctorSource === "Global") {
          const globalProctors = allDepartments.flatMap(d => d.proctors);
          proctor = globalProctors.find(validateProctor);
        }

        daySubjects.forEach(sub => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: currentDate,
            start_time: startTime, end_time: endTime, room: chosenRoomNumbers[s],
            proctor: proctor?.name || "UNASSIGNED (Shift Conflict)"
          });
        });
      }
    }
    onGenerate(finalGeneratedData, examDates);
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden mb-12">
      {/* DEPT HEADER */}
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <div className="flex items-center gap-4">
          <div className="bg-blue-600 p-3 rounded-2xl"><Layers size={24}/></div>
          <h2 className="text-3xl font-black uppercase tracking-tighter">{deptName} ({deptCode})</h2>
        </div>
      </div>

      {/* NAVIGATION TABS */}
      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-10">
        {/* --- PROCTORS TAB (STRICT TIME/DAY WINDOWS) --- */}
        {activeTab === 'proctors' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-5 gap-4 bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100 shadow-inner">
              <div className="md:col-span-1">
                <label className="text-[9px] font-black text-emerald-700 uppercase block mb-1">Instructor Name</label>
                <input value={pName} onChange={e=>setPName(e.target.value)} placeholder="E.g. DR. SMITH" className="w-full p-3 rounded-xl text-xs font-bold border-none shadow-sm" />
              </div>
              <div className="md:col-span-1">
                <label className="text-[9px] font-black text-emerald-700 uppercase block mb-1">Service Dates</label>
                <div className="flex gap-1">
                  <input type="date" value={pDayStart} onChange={e=>setPDayStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px] font-bold" />
                  <input type="date" value={pDayEnd} onChange={e=>setPDayEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px] font-bold" />
                </div>
              </div>
              <div className="md:col-span-1">
                <label className="text-[9px] font-black text-emerald-700 uppercase block mb-1">Shift Hours</label>
                <div className="flex gap-1">
                  <input type="time" value={pTimeStart} onChange={e=>setPTimeStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px] font-bold" />
                  <input type="time" value={pTimeEnd} onChange={e=>setPTimeEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px] font-bold" />
                </div>
              </div>
              <div className="flex items-end">
                <button onClick={handleAddProctor} className="w-full h-[45px] bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black text-[10px] uppercase shadow-lg shadow-emerald-200 transition-all active:scale-95">Register Staff</button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {proctors.map(p => (
                <div key={p.id} className="flex justify-between items-center p-6 bg-white border-2 border-slate-50 rounded-[2rem] shadow-sm hover:border-emerald-300 transition-all group">
                  <div className="flex items-center gap-4">
                    <div className="bg-emerald-100 p-3 rounded-2xl text-emerald-600"><Users size={20}/></div>
                    <div>
                      <p className="font-black text-sm text-slate-800 uppercase leading-none mb-2">{p.name}</p>
                      <div className="flex gap-4">
                        <span className="text-[9px] font-black text-slate-400 uppercase flex items-center gap-1"><Calendar size={10}/> {p.dayStart} — {p.dayEnd}</span>
                        <span className="text-[9px] font-black text-blue-500 uppercase flex items-center gap-1"><Clock size={10}/> {p.timeStart} — {p.timeEnd}</span>
                      </div>
                    </div>
                  </div>
                  <button onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} className="text-slate-200 group-hover:text-rose-500 transition-all"><Trash2 size={18}/></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* --- GENERATE TAB (FULL CONSTRAINTS) --- */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-12 opacity-10"><Play size={150} fill="currentColor"/></div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 relative z-10">

              <div className="space-y-8">
                <h4 className="text-blue-400 font-black text-xs uppercase tracking-[0.5em] flex items-center gap-2"><Calendar size={16}/> Schedule Setup</h4>
                <div className="space-y-6 bg-slate-800/40 p-8 rounded-[2rem] border border-white/5">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase block mb-3">Total Exam Days</label>
                    <input type="number" value={examDays} onChange={e=>handleExamDayChange(e.target.value)} className="w-full bg-slate-950 p-4 rounded-2xl text-2xl font-black text-blue-500 border border-slate-700" />
                  </div>
                  <div className="space-y-3 max-h-[160px] overflow-y-auto custom-scrollbar pr-2">
                    {examDates.map((d, i) => (
                      <div key={i} className="flex items-center gap-4 bg-slate-950/50 p-4 rounded-2xl border border-white/5">
                        <span className="bg-blue-600/20 text-blue-400 w-8 h-8 rounded-lg flex items-center justify-center font-black text-[10px]">D{i+1}</span>
                        <input type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="bg-transparent flex-1 outline-none text-xs font-black uppercase text-white" />
                      </div>
                    ))}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-950/50 p-4 rounded-2xl border border-white/5">
                      <label className="text-[8px] font-black text-slate-500 uppercase block mb-1">Time Start</label>
                      <input type="time" value={startTime} onChange={e=>setStartTime(e.target.value)} className="bg-transparent w-full text-xl font-black text-blue-400 outline-none" />
                    </div>
                    <div className="bg-slate-950/50 p-4 rounded-2xl border border-white/5">
                      <label className="text-[8px] font-black text-slate-500 uppercase block mb-1">Time End</label>
                      <input type="time" value={endTime} onChange={e=>setEndTime(e.target.value)} className="bg-transparent w-full text-xl font-black text-blue-400 outline-none" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-8">
                <h4 className="text-emerald-400 font-black text-xs uppercase tracking-[0.5em] flex items-center gap-2"><ShieldCheck size={16}/> Engine Parameters</h4>
                <div className="space-y-6 bg-slate-800/40 p-8 rounded-[2rem] border border-white/5">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase block mb-3 tracking-widest">Year Level</label>
                      <select value={selectedYear} onChange={e=>setSelectedYear(e.target.value)} className="w-full bg-slate-950 p-4 rounded-2xl font-black text-blue-400 text-sm border border-slate-700 outline-none">
                        {[1,2,3,4,5].map(y => <option key={y} value={y}>YEAR {y}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase block mb-3 tracking-widest">Sections</label>
                      <input type="number" value={sectionCount} onChange={e=>setSectionCount(e.target.value)} className="w-full bg-slate-950 p-4 rounded-2xl font-black text-emerald-400 text-center text-lg border border-slate-700" />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[8px] font-black text-slate-500 uppercase block mb-2">Proctor Logic</label>
                      <select value={proctorSource} onChange={e=>setProctorSource(e.target.value)} className="w-full bg-slate-950 p-3 rounded-xl font-black text-[10px] border border-slate-700 outline-none"><option>Department</option><option>Global</option></select>
                    </div>
                    <div>
                      <label className="text-[8px] font-black text-slate-500 uppercase block mb-2">Room Logic</label>
                      <select value={roomSource} onChange={e=>setRoomSource(e.target.value)} className="w-full bg-slate-950 p-3 rounded-xl font-black text-[10px] border border-slate-700 outline-none"><option>Department</option><option>Global</option></select>
                    </div>
                  </div>
                  <button onClick={handleGenerateClick} className="w-full bg-blue-600 hover:bg-blue-500 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.5em] flex items-center justify-center gap-4 shadow-[0_20px_60px_rgba(37,99,235,0.4)] transition-all active:scale-95 active:shadow-none">
                    <Play size={24} fill="currentColor"/> Run System Engine
                  </button>
                </div>
              </div>

            </div>
          </div>
        )}

        {/* --- SUBJECTS TAB (Same logic) --- */}
        {activeTab === 'subjects' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-slate-50 p-6 rounded-3xl border border-slate-100">
              <select className="p-3 rounded-xl font-black text-xs border-2 border-white shadow-sm" onChange={(e) => setSelectedYear(e.target.value)}>
                {[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-3 rounded-xl font-black text-xs border-2 border-white shadow-sm" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-3 rounded-xl font-black text-xs border-2 border-white shadow-sm" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value;
                const n = document.getElementById(`sN-${deptId}`).value;
                if(c && n) {
                  onUpdate('subjects', { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: c.toUpperCase(), name: n }] });
                  document.getElementById(`sC-${deptId}`).value = '';
                  document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-slate-900 text-white rounded-xl font-black text-xs uppercase">Add Subject</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {subjects[selectedYear].map((s, i) => (
                <div key={i} className="flex justify-between items-center p-5 bg-white border-2 border-slate-50 rounded-2xl shadow-sm">
                  <span className="font-black text-xs">{s.code}: <span className="text-slate-400 italic font-medium">{s.name}</span></span>
                  <button onClick={() => onUpdate('subjects', {...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)}) }><Trash2 size={16} className="text-slate-300 hover:text-rose-500 transition-colors" /></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* --- ROOMS TAB (Dept vs Global) --- */}
        {activeTab === 'rooms' && (
          <div className="space-y-8">
            <div className="flex flex-col md:flex-row gap-4 bg-amber-50 p-6 rounded-[2rem] border border-amber-100 shadow-inner">
              <input value={roomNum} onChange={e=>setRoomNum(e.target.value)} placeholder="ROOM NO." className="flex-1 p-3 rounded-xl font-black text-xs border-none shadow-sm" />
              <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Department'}]); setRoomNum(""); } }} className="bg-amber-600 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg shadow-amber-200">Dept Only</button>
              <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Global'}]); setRoomNum(""); } }} className="bg-slate-800 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg shadow-slate-300">Global Pool</button>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-8 bg-white border-2 border-slate-50 rounded-[2.5rem] text-center relative group hover:border-amber-400 transition-all shadow-sm">
                  <span className="font-black text-2xl text-slate-800 block mb-1">{r.number}</span>
                  <span className={`text-[8px] font-black uppercase px-2 py-1 rounded-full ${r.type === 'Global' ? 'bg-slate-900 text-white' : 'bg-amber-100 text-amber-700'}`}>{r.type}</span>
                  <button className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-all text-slate-300 hover:text-rose-500" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={14}/></button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
